shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

    :host {
      --paper: #faf8f4;
      --paper-card: #f3efe6;
      --paper-dark: #ebe5d8;
      --ink: #141413;
      --body: #242220;
      --muted: #646059;
      --line: #e4dfd3;
      --line-strong: #c8c0b0;
      --accent: #b85d19;
      --crimson: #9e2a2b;
      --navy-bg: #0f1d2b;
      --navy-card: #16283a;
      --navy-line: #294057;
      --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
      --font-serif: 'Lora', 'Noto Serif SC', Georgia, serif;
      --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
      --font-mono: 'JetBrains Mono', 'Noto Sans SC', monospace;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      background-color: var(--paper);
      color: var(--body);
      font-family: var(--font-serif);
      -webkit-font-smoothing: antialiased;
      scroll-behavior: smooth;
    }

    /* Strictly enforced bilingual toggle rules */
    :host([lang="zh-CN"]) .lang-en { display: none !important; }
    :host([lang="en"]) .lang-cn { display: none !important; }

    .wsj-shadow-body {
      background-color: var(--paper);
      overflow-x: hidden;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
    }

    /* Highlight styling */
    mark.ed-hl {
      background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
      color: inherit;
      padding: 0 2px;
      font-weight: 600;
    }

    .dark-surface mark.ed-hl {
      background: linear-gradient(180deg, transparent 55%, rgba(235, 138, 68, 0.35) 55%);
      color: #fff;
    }

    /* Sticky Top Masthead */
    .masthead {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(250, 248, 244, 0.94);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--line-strong);
    }

    .masthead-inner {
      max-width: 1180px;
      margin: 0 auto;
      padding: 0.7rem 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand-group {
      display: flex;
      align-items: center;
      gap: 0.85rem;
      flex-wrap: wrap;
    }

    .wsj-logo {
      font-family: var(--font-display);
      font-weight: 800;
      font-size: 1.05rem;
      letter-spacing: 0.06em;
      color: var(--ink);
      text-transform: uppercase;
    }

    .masthead-divider {
      width: 1px;
      height: 14px;
      background: var(--line-strong);
    }

    .section-tag {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--accent);
      background: rgba(184, 93, 25, 0.1);
      padding: 0.2rem 0.5rem;
      border-radius: 2px;
    }

    .page-folio {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      color: var(--muted);
      letter-spacing: 0.04em;
    }

    .lang-switch {
      display: inline-flex;
      border: 1px solid var(--line-strong);
      background: var(--paper-card);
      border-radius: 3px;
      overflow: hidden;
      flex-shrink: 0;
    }

    .lang-btn {
      appearance: none;
      border: none;
      background: transparent;
      font-family: var(--font-mono);
      font-size: 0.75rem;
      font-weight: 600;
      padding: 0.35rem 0.75rem;
      cursor: pointer;
      color: var(--muted);
      transition: all 0.18s ease;
    }

    .lang-btn.active {
      background: var(--ink);
      color: var(--paper);
    }

    /* Main Editorial Container */
    .editorial-shell {
      max-width: 1180px;
      width: 100%;
      margin: 0 auto;
      padding: 2.75rem 1.5rem 4.5rem;
    }

    /* Hero Header / Forensic Incident Banner */
    .incident-header {
      border-top: 3px double var(--ink);
      border-bottom: 1px solid var(--line-strong);
      padding: 2.25rem 0 2rem;
      margin-bottom: 2.5rem;
    }

    .kicker-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-bottom: 1.1rem;
    }

    .kicker-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-family: var(--font-mono);
      font-size: 0.76rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--crimson);
    }

    .pulse-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background-color: var(--crimson);
      box-shadow: 0 0 0 3px rgba(158, 42, 43, 0.2);
    }

    .incident-code {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      color: var(--muted);
      letter-spacing: 0.06em;
    }

    .headline {
      font-family: var(--font-display);
      font-weight: 800;
      font-size: clamp(2.1rem, 4.2vw, 3.35rem);
      line-height: 1.16;
      color: var(--ink);
      letter-spacing: -0.015em;
      margin-bottom: 1.35rem;
      max-width: 24ch;
    }

    :host([lang="zh-CN"]) .headline {
      line-height: 1.24;
      letter-spacing: 0.01em;
      max-width: 100%;
    }

    .meta-bar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1.1rem;
      border-top: 1px solid var(--line);
      font-family: var(--font-sans);
      font-size: 0.84rem;
      color: var(--muted);
    }

    .byline {
      font-weight: 600;
      color: var(--ink);
      letter-spacing: 0.03em;
    }

    .dateline {
      font-family: var(--font-mono);
      font-size: 0.78rem;
    }

    /* Executive Incident Matrix (Top Forensic Strip) */
    .forensic-strip {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1px;
      background: var(--line-strong);
      border: 1px solid var(--line-strong);
      margin-bottom: 3rem;
    }

    .forensic-cell {
      background: var(--paper-card);
      padding: 1.15rem 1.25rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .cell-tag {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      text-transform: uppercase;
      letter-spacing: 0.09em;
      color: var(--muted);
      margin-bottom: 0.45rem;
    }

    .cell-value {
      font-family: var(--font-display);
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--ink);
      line-height: 1.25;
      margin-bottom: 0.35rem;
    }

    .cell-value.alert {
      color: var(--crimson);
    }

    .cell-sub {
      font-family: var(--font-sans);
      font-size: 0.76rem;
      color: var(--muted);
      line-height: 1.4;
    }

    /* Main Asymmetric Investigative Grid */
    .investigative-grid {
      display: grid;
      grid-template-columns: 310px 1fr;
      gap: 3rem;
      align-items: start;
    }

    /* Left Forensic Dossier Rail */
    .dossier-rail {
      position: sticky;
      top: 4.5rem;
      display: flex;
      flex-direction: column;
      gap: 1.5rem;
    }

    .dossier-box {
      background: var(--paper-card);
      border: 1px solid var(--line-strong);
      border-top: 3px solid var(--ink);
      padding: 1.35rem;
    }

    .dossier-title {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--ink);
      padding-bottom: 0.65rem;
      margin-bottom: 1rem;
      border-bottom: 1px solid var(--line-strong);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .dossier-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 0.9rem;
    }

    .dossier-item {
      display: flex;
      flex-direction: column;
      gap: 0.2rem;
      padding-bottom: 0.85rem;
      border-bottom: 1px dashed var(--line-strong);
    }

    .dossier-item:last-child {
      padding-bottom: 0;
      border-bottom: none;
    }

    .dossier-label {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      text-transform: uppercase;
      color: var(--accent);
      letter-spacing: 0.06em;
    }

    .dossier-desc {
      font-family: var(--font-sans);
      font-size: 0.84rem;
      color: var(--body);
      line-height: 1.48;
      font-weight: 500;
    }

    /* Derived Quote Card in Sidebar */
    .sidebar-quote-card {
      background: var(--navy-bg);
      color: var(--paper);
      padding: 1.4rem;
      border-left: 4px solid var(--accent);
    }

    .sidebar-quote-kicker {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: #e89958;
      margin-bottom: 0.65rem;
    }

    .sidebar-quote-card .quote-text {
      font-family: var(--font-serif);
      font-size: 0.93rem;
      line-height: 1.62;
      color: #f4f1ea;
      margin-bottom: 0.75rem;
    }

    .sidebar-quote-card .quote-attrib {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      color: #9ab0c7;
    }

    /* Right Primary Narrative Column */
    .narrative-stream {
      display: flex;
      flex-direction: column;
      gap: 2rem;
      min-width: 0;
    }

    .chapter-block {
      display: flex;
      flex-direction: column;
      gap: 1.35rem;
    }

    .chapter-header {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      padding-bottom: 0.55rem;
      border-bottom: 1px solid var(--line-strong);
    }

    .chapter-num {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      font-weight: 700;
      color: var(--paper);
      background: var(--ink);
      padding: 0.15rem 0.45rem;
      letter-spacing: 0.06em;
    }

    .chapter-title {
      font-family: var(--font-sans);
      font-size: 0.82rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--muted);
    }

    .prose-p {
      font-family: var(--font-serif);
      font-size: 1.125rem;
      line-height: 1.82;
      color: var(--body);
    }

    :host([lang="zh-CN"]) .prose-p {
      font-size: 1.14rem;
      line-height: 1.92;
      text-align: justify;
    }

    /* Lead paragraph treatment without CSS ::first-letter */
    .prose-lead {
      font-size: 1.28rem;
      line-height: 1.72;
      font-weight: 600;
      color: var(--ink);
      border-left: 4px solid var(--accent);
      padding-left: 1.25rem;
      background: linear-gradient(90deg, rgba(184, 93, 25, 0.06), transparent 85%);
      padding-top: 0.35rem;
      padding-bottom: 0.35rem;
    }

    :host([lang="zh-CN"]) .prose-lead {
      font-size: 1.25rem;
      line-height: 1.85;
    }

    /* Evidence Exhibit Card (Inline SVG Container) */
    .exhibit-card {
      background: var(--paper-card);
      border: 1px solid var(--line-strong);
      padding: 1.5rem;
      margin: 0.5rem 0;
    }

    .exhibit-header {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-bottom: 1rem;
      padding-bottom: 0.65rem;
      border-bottom: 1px solid var(--line);
    }

    .exhibit-title {
      font-family: var(--font-sans);
      font-size: 0.92rem;
      font-weight: 700;
      color: var(--ink);
    }

    .exhibit-tag {
      font-family: var(--font-mono);
      font-size: 0.7rem;
      color: var(--accent);
      text-transform: uppercase;
      letter-spacing: 0.06em;
    }

    .svg-wrap {
      width: 100%;
      overflow: hidden;
    }

    .exhibit-caption {
      margin-top: 0.85rem;
      font-family: var(--font-sans);
      font-size: 0.78rem;
      color: var(--muted);
      line-height: 1.45;
    }

    /* Statement Callout Box for p5 */
    .statement-dossier {
      background: var(--paper-card);
      border-left: 4px solid var(--ink);
      border-top: 1px solid var(--line-strong);
      border-right: 1px solid var(--line-strong);
      border-bottom: 1px solid var(--line-strong);
      padding: 1.5rem 1.65rem;
      position: relative;
    }

    .statement-kicker {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--accent);
      margin-bottom: 0.6rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .statement-dossier .prose-p {
      font-size: 1.14rem;
      font-style: italic;
      color: var(--ink);
    }

    :host([lang="zh-CN"]) .statement-dossier .prose-p {
      font-style: normal;
      font-weight: 600;
    }

    /* Climactic Law Enforcement Verdict Box for p6 + p7 */
    .verdict-panel {
      background: var(--navy-bg);
      color: var(--paper);
      padding: 2rem;
      border-top: 4px solid var(--crimson);
      display: flex;
      flex-direction: column;
      gap: 1.5rem;
    }

    .verdict-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 0.75rem;
      border-bottom: 1px solid var(--navy-line);
      padding-bottom: 0.9rem;
    }

    .verdict-badge {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: #ff8585;
      background: rgba(158, 42, 43, 0.35);
      border: 1px solid rgba(255, 133, 133, 0.35);
      padding: 0.25rem 0.65rem;
    }

    .verdict-meta {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      color: #9ab0c7;
    }

    .verdict-panel .prose-p {
      color: #e9e4da;
    }

    .police-verdict-quote {
      background: var(--navy-card);
      border-left: 4px solid #ff6b6b;
      padding: 1.35rem 1.5rem;
    }

    .police-verdict-quote .prose-p {
      font-family: var(--font-display);
      font-size: 1.24rem;
      line-height: 1.58;
      color: #ffffff;
    }

    :host([lang="zh-CN"]) .police-verdict-quote .prose-p {
      font-size: 1.2rem;
      line-height: 1.75;
    }

    /* Footer */
    .editorial-footer {
      margin-top: auto;
      border-top: 1px solid var(--line-strong);
      background: var(--paper-card);
      padding: 2rem 1.5rem;
    }

    .footer-inner {
      max-width: 1180px;
      margin: 0 auto;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      font-family: var(--font-mono);
      font-size: 0.74rem;
      color: var(--muted);
    }

    /* Responsive Breakpoints */
    @media (max-width: 960px) {
      .forensic-strip {
        grid-template-columns: repeat(2, 1fr);
      }
      .investigative-grid {
        grid-template-columns: 1fr;
        gap: 2.25rem;
      }
      .dossier-rail {
        position: static;
        order: 2;
      }
      .narrative-stream {
        order: 1;
      }
    }

    @media (max-width: 600px) {
      .masthead-inner {
        padding: 0.6rem 1rem;
      }
      .page-folio {
        display: none;
      }
      .editorial-shell {
        padding: 1.5rem 1rem 3rem;
      }
      .forensic-strip {
        grid-template-columns: 1fr;
      }
      .headline {
        font-size: 1.85rem;
      }
      .prose-lead {
        font-size: 1.12rem;
        padding-left: 0.9rem;
      }
      .prose-p {
        font-size: 1.04rem;
      }
      .exhibit-card,
      .statement-dossier,
      .verdict-panel {
        padding: 1.15rem;
      }
    }
